"use client";

import React, { useState, useMemo, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { ALL_ADS, CATEGORIES, POPULAR_METRO_CITIES } from "@/lib/data";
import { AdCard } from "@/components/services/AdCard";
import { Search, MapPin, SlidersHorizontal, ArrowUpDown } from "lucide-react";

function AdsContent() {
  const searchParams = useSearchParams();
  const initialQ = searchParams?.get("q") || "";
  const initialCity = searchParams?.get("city") || "";
  const initialCategory = searchParams?.get("category") || "";

  const [searchQuery, setSearchQuery] = useState(initialQ);
  const [selectedCity, setSelectedCity] = useState(initialCity);
  const [selectedCategory, setSelectedCategory] = useState(initialCategory);
  const [sortBy, setSortBy] = useState<"featured" | "price-asc" | "price-desc">("featured");

  const filteredAds = useMemo(() => {
    return ALL_ADS.filter((ad) => {
      const matchQ =
        !searchQuery.trim() ||
        ad.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        ad.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        ad.categoryName.toLowerCase().includes(searchQuery.toLowerCase());

      const matchCity =
        !selectedCity.trim() ||
        ad.city.toLowerCase() === selectedCity.toLowerCase() ||
        ad.area.toLowerCase().includes(selectedCity.toLowerCase());

      const matchCategory =
        !selectedCategory.trim() || ad.categorySlug === selectedCategory;

      return matchQ && matchCity && matchCategory;
    }).sort((a, b) => {
      if (sortBy === "price-asc") return a.priceNum - b.priceNum;
      if (sortBy === "price-desc") return b.priceNum - a.priceNum;
      if (a.featured && !b.featured) return -1;
      if (!a.featured && b.featured) return 1;
      return 0;
    });
  }, [searchQuery, selectedCity, selectedCategory, sortBy]);

  return (
    <div className="min-h-screen py-10 bg-neutral-50/60">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Header Breadcrumb / Title */}
        <div className="mb-8">
          <div className="text-xs text-neutral-500 mb-2 font-medium">
            <span>Home</span> <span className="mx-1">/</span> <span className="text-neutral-900 font-bold">Browse Ads</span>
          </div>
          <h1 className="text-3xl sm:text-4xl font-extrabold text-neutral-900 tracking-tight">
            Browse <span className="bg-gradient-to-r from-blue-600 to-fb8500 bg-clip-text text-transparent">Services</span>
          </h1>
          <p className="mt-1 text-sm text-neutral-600">
            Find verified pest exterminators, cleaners, technicians and handymen across India
          </p>
        </div>

        {/* Filter Controls Bar */}
        <div className="bg-white rounded-3xl p-4 sm:p-5 shadow-sm border border-neutral-200/80 mb-8 space-y-4">
          <div className="flex flex-col md:flex-row gap-3 items-center">
            {/* Search Input */}
            <div className="relative flex-1 w-full">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search services, e.g. cockroach control, pipe leak, AC..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-neutral-50 border border-neutral-200 text-sm font-medium text-neutral-900 placeholder-neutral-400 focus:outline-none focus:border-fb8500 transition-colors"
              />
            </div>

            {/* City Selector */}
            <div className="relative w-full md:w-56">
              <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-fb8500" />
              <select
                value={selectedCity}
                onChange={(e) => setSelectedCity(e.target.value)}
                className="w-full pl-9 pr-8 py-2.5 rounded-xl bg-neutral-50 border border-neutral-200 text-sm font-medium text-neutral-900 focus:outline-none focus:border-fb8500 appearance-none cursor-pointer"
              >
                <option value="">All Cities</option>
                {POPULAR_METRO_CITIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
              <span className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-xs text-neutral-400">
                ▼
              </span>
            </div>

            {/* Sort Dropdown */}
            <div className="relative w-full md:w-52">
              <ArrowUpDown className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as any)}
                className="w-full pl-9 pr-8 py-2.5 rounded-xl bg-neutral-50 border border-neutral-200 text-sm font-medium text-neutral-900 focus:outline-none focus:border-fb8500 appearance-none cursor-pointer"
              >
                <option value="featured">Featured First</option>
                <option value="price-asc">Price: Low to High</option>
                <option value="price-desc">Price: High to Low</option>
              </select>
              <span className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-xs text-neutral-400">
                ▼
              </span>
            </div>
          </div>

          {/* Category Filter Pills (Horizontal scrollable) */}
          <div className="pt-2 border-t border-neutral-100 flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none">
            <button
              onClick={() => setSelectedCategory("")}
              className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all shrink-0 ${
                selectedCategory === ""
                  ? "bg-fb8500 text-white shadow-sm"
                  : "bg-neutral-100 text-neutral-700 hover:bg-neutral-200"
              }`}
            >
              All Categories
            </button>
            {CATEGORIES.map((cat) => (
              <button
                key={cat.slug}
                onClick={() => setSelectedCategory(cat.slug)}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all shrink-0 flex items-center gap-1.5 ${
                  selectedCategory === cat.slug
                    ? "bg-fb8500 text-white shadow-sm"
                    : "bg-neutral-100 text-neutral-700 hover:bg-neutral-200"
                }`}
              >
                <span>{cat.icon}</span>
                <span>{cat.name}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Results Count & Badges */}
        <div className="flex items-center justify-between gap-4 mb-6 text-sm text-neutral-600">
          <p>
            Showing <strong className="text-neutral-900">{filteredAds.length}</strong> services
            {selectedCity && <span> in <strong className="text-neutral-900">{selectedCity}</strong></span>}
            {selectedCategory && (
              <span> in <strong className="text-neutral-900">{CATEGORIES.find((c) => c.slug === selectedCategory)?.name}</strong></span>
            )}
          </p>

          {(searchQuery || selectedCity || selectedCategory) && (
            <button
              onClick={() => {
                setSearchQuery("");
                setSelectedCity("");
                setSelectedCategory("");
              }}
              className="text-xs font-semibold text-fb8500 hover:underline"
            >
              Clear filters
            </button>
          )}
        </div>

        {/* Ads Cards Grid */}
        {filteredAds.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8">
            {filteredAds.map((ad) => (
              <AdCard key={ad.id} ad={ad} />
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-3xl p-12 text-center border border-neutral-200 max-w-lg mx-auto">
            <div className="text-4xl mb-3">🔍</div>
            <h3 className="text-lg font-bold text-neutral-900">No services found</h3>
            <p className="text-sm text-neutral-500 mt-1">
              Try adjusting your search terms or clearing city/category filters.
            </p>
            <button
              onClick={() => {
                setSearchQuery("");
                setSelectedCity("");
                setSelectedCategory("");
              }}
              className="mt-5 px-5 py-2.5 rounded-xl font-bold text-xs text-white primary-gradient"
            >
              Reset All Filters
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function AdsPage() {
  return (
    <Suspense
      fallback={
        <div className="py-24 text-center text-neutral-500">
          <div className="animate-pulse text-lg">Loading WrkZone services…</div>
        </div>
      }
    >
      <AdsContent />
    </Suspense>
  );
}
