import React from "react";
import Link from "next/link";
import { ServiceAd } from "@/lib/data";

interface AdCardProps {
  ad: ServiceAd;
}

export function AdCard({ ad }: AdCardProps) {
  // Category banner pastel background & pill badge colors matching original wrkzone.com
  const catStyles: Record<string, { bg: string; badge: string }> = {
    "pest-control": {
      bg: "linear-gradient(135deg, #ecfccb 0%, #d9f99d 100%)",
      badge: "#84cc16",
    },
    cleaning: {
      bg: "linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)",
      badge: "#f59e0b",
    },
    "ac-repair": {
      bg: "linear-gradient(135deg, #cffafe 0%, #a5f3fc 100%)",
      badge: "#06b6d4",
    },
    plumbing: {
      bg: "linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)",
      badge: "#3b82f6",
    },
    carpentry: {
      bg: "linear-gradient(135deg, #ffedd5 0%, #fed7aa 100%)",
      badge: "#d97706",
    },
    electrician: {
      bg: "linear-gradient(135deg, #fef9c3 0%, #fef08a 100%)",
      badge: "#eab308",
    },
    movers: {
      bg: "linear-gradient(135deg, #ede9fe 0%, #ddd6fe 100%)",
      badge: "#8b5cf6",
    },
  };

  const currentStyle = catStyles[ad.categorySlug] || {
    bg: "linear-gradient(135deg, #ffedd5 0%, #fed7aa 100%)",
    badge: "#fb8500",
  };

  const isNegotiable =
    ad.title.toLowerCase().includes("cleaning") ||
    ad.title.toLowerCase().includes("carpentry") ||
    ad.price.toLowerCase().includes("negotiable");

  return (
    <Link
      href={`/ads/${ad.id}`}
      className="card-lift group flex flex-col overflow-hidden rounded-2xl bg-white ring-1 ring-neutral-200/80 shadow-sm hover:shadow-md hover:ring-[#fb8500] transition-all cursor-pointer"
    >
      {/* Top Banner with Illustration & Badges */}
      <div className="relative h-44 overflow-hidden">
        <div
          className="flex h-full w-full items-center justify-center text-6xl group-hover:scale-105 transition-transform duration-300"
          style={{ background: currentStyle.bg }}
        >
          {ad.categoryIcon}
        </div>
        {ad.featured && (
          <span className="absolute left-3 top-3 rounded-full bg-white/80 backdrop-blur-xs px-2.5 py-1 text-[11px] font-semibold text-neutral-700 shadow-xs border border-white/50">
            ⭐ Featured
          </span>
        )}
        <span
          className="absolute right-3 top-3 rounded-full px-2.5 py-1 text-[11px] font-bold text-white shadow"
          style={{ background: currentStyle.badge }}
        >
          {ad.categoryIcon} {ad.categoryName}
        </span>
      </div>

      {/* Card Content Body */}
      <div className="flex flex-1 flex-col p-4">
        <h3 className="line-clamp-1 font-bold font-serif text-neutral-900 group-hover:text-[#fb8500] transition text-base">
          {ad.title}
        </h3>
        <p className="mt-1 line-clamp-2 text-sm text-neutral-600 leading-relaxed font-normal">
          {ad.description}
        </p>

        <div className="mt-3 flex items-center gap-1.5 text-xs sm:text-sm text-neutral-600">
          <span>📍</span>
          <span className="truncate">
            {ad.area ? `${ad.area}, ` : ""}
            {ad.city}
          </span>
        </div>

        <div className="mt-3 flex items-center justify-between border-t border-neutral-100 pt-3">
          <span className="font-extrabold text-neutral-900 text-base">
            {ad.price}
            {isNegotiable && !ad.price.includes("Negotiable") ? " · Negotiable" : ""}
          </span>
          <span className="text-xs text-neutral-400 font-normal">
            {ad.postedAgo}
          </span>
        </div>
      </div>
    </Link>
  );
}
